    this.blurPass = this.blurPassLarge;
    this.vertexBuffer = null;
    this.sampler = null;
    this.uniformData = null;
    this.uniformBuffer = null;
    this.layout = null;
    this.pipeline = null;
    this.depthDebugLayout = null;
    this.depthDebugPipeline = null;
    this.focusDebugLayout = null;
